import { useDispatch } from 'react-redux';
import { getTranslation, createNewTab } from '../../../../shared/chromeApi';
import { toggleBookmarksNotification } from '../slice';

import styles from './styles.module.scss';

const BookmarksBar = () => {
  const dispatch = useDispatch();

  const handleClose = () => {
    dispatch(toggleBookmarksNotification(true));
  };
  const handleHelp = () => {
    handleClose();
    createNewTab('chrome://settings/appearance');
  };

  return (
    <section className={styles.bookmarksHelp}>
      <h4
        dangerouslySetInnerHTML={{
          __html: getTranslation('notification_bookmarks_title'),
        }}
      />
      <button onClick={handleHelp} className={styles.button}>
        {getTranslation('notification_bookmarks_help')}
      </button>

      {/*<button onClick={handleClose} className={styles.close}>*/}
      {/*  <span>{getTranslation('notification_bookmarks_dismiss')}</span>*/}
      {/*</button>*/}
    </section>
  );
};

export default BookmarksBar;
